  1→// Piece type constants (0-6)
  2→export const PIECE_TYPES = {
  3→  NONE: 0,
  4→  KING: 1,
  5→  PAWN: 2,
  6→  KNIGHT: 3,
  7→  ROOK: 4,
  8→  BISHOP: 5,
  9→  QUEEN: 6
 10→};
 11→
 12→// Color constants
 13→export const COLORS = {
 14→  WHITE: 'white',
 15→  BLACK: 'black'
 16→};
 17→
 18→// White pieces (positive numbers 1-6)
 19→export const WHITE_PIECES = {
 20→  KING: 1,
 21→  PAWN: 2,
 22→  KNIGHT: 3,
 23→  ROOK: 4,
 24→  BISHOP: 5,
 25→  QUEEN: 6
 26→};
 27→
 28→// Black pieces (negative numbers -1 to -6)
 29→export const BLACK_PIECES = {
 30→  KING: -1,
 31→  PAWN: -2,
 32→  KNIGHT: -3,
 33→  ROOK: -4,
 34→  BISHOP: -5,
 35→  QUEEN: -6
 36→};
 37→
 38→// Helper function to get piece color
 39→export const getPieceColor = (piece) => {
 40→  if (piece > 0) return COLORS.WHITE;
 41→  if (piece < 0) return COLORS.BLACK;
 42→  return null;
 43→};
 44→
 45→// Helper function to get piece type
 46→export const getPieceType = (piece) => {
 47→  return Math.abs(piece);
 48→};
 49→
 50→// Helper function to check if piece is white
 51→export const isWhitePiece = (piece) => piece > 0;
 52→
 53→// Helper function to check if piece is black
 54→export const isBlackPiece = (piece) => piece < 0;
 55→
 56→// Standard starting position in FEN notation
 57→export const STARTING_FEN = 'rnbqkbnr/pppppppp/8/8/8/8/PPPPPPPP/RNBQKBNR';
 58→
 59→// Unicode chess piece symbols
 60→export const PIECE_SYMBOLS = {
 61→  // White pieces
 62→  1: '♔',   // White King
 63→  2: '♙',   // White Pawn
 64→  3: '♘',   // White Knight
 65→  4: '♖',   // White Rook
 66→  5: '♗',   // White Bishop
 67→  6: '♕',   // White Queen
 68→  // Black pieces
 69→  '-1': '♚',  // Black King
 70→  '-2': '♟',  // Black Pawn
 71→  '-3': '♞',  // Black Knight
 72→  '-4': '♜',  // Black Rook
 73→  '-5': '♝',  // Black Bishop
 74→  '-6': '♛',  // Black Queen
 75→};
 76→
 77→// FEN character to piece number mapping
 78→const FEN_TO_PIECE = {
 79→  'K': 1,   // White King
 80→  'P': 2,   // White Pawn
 81→  'N': 3,   // White Knight
 82→  'R': 4,   // White Rook
 83→  'B': 5,   // White Bishop
 84→  'Q': 6,   // White Queen
 85→  'k': -1,  // Black King
 86→  'p': -2,  // Black Pawn
 87→  'n': -3,  // Black Knight
 88→  'r': -4,  // Black Rook
 89→  'b': -5,  // Black Bishop
 90→  'q': -6,  // Black Queen
 91→};
 92→
 93→// Parse FEN notation to board array
 94→export const parseFEN = (fen) => {
 95→  const board = new Array(64).fill(0);
 96→  const ranks = fen.split('/');
 97→
 98→  let squareIndex = 0;
 99→
100→  for (let rank of ranks) {
101→    for (let char of rank) {
102→      if (isNaN(char)) {
103→        // It's a piece
104→        board[squareIndex] = FEN_TO_PIECE[char];
105→        squareIndex++;
106→      } else {
107→        // It's a number indicating empty squares
108→        const emptySquares = parseInt(char);
109→        squareIndex += emptySquares;
110→      }
111→    }
112→  }
113→
114→  return board;
115→};
116→
117→// Initial chess board state (64 squares, 0-63)
118→export const INITIAL_BOARD = parseFEN(STARTING_FEN);
