  1→import { PIECE_TYPES, isWhitePiece, isBlackPiece } from './constants';
  2→
  3→// Helper to convert index to row/col
  4→export const indexToRowCol = (index) => {
  5→  const row = Math.floor(index / 8);
  6→  const col = index % 8;
  7→  return { row, col };
  8→};
  9→
 10→// Helper to convert row/col to index
 11→export const rowColToIndex = (row, col) => {
 12→  return row * 8 + col;
 13→};
 14→
 15→// Validate pawn moves
 16→export const isValidPawnMove = (board, fromIndex, toIndex, enPassantTarget) => {
 17→  const piece = board[fromIndex];
 18→  const targetPiece = board[toIndex];
 19→  const pieceType = Math.abs(piece);
 20→
 21→  if (pieceType !== PIECE_TYPES.PAWN) {
 22→    return false;
 23→  }
 24→
 25→  const { row: fromRow, col: fromCol } = indexToRowCol(fromIndex);
 26→  const { row: toRow, col: toCol } = indexToRowCol(toIndex);
 27→
 28→  const isWhite = isWhitePiece(piece);
 29→  const direction = isWhite ? -1 : 1; // White moves up (negative), black moves down (positive)
 30→  const startingRow = isWhite ? 6 : 1; // Starting row for pawns
 31→
 32→  const rowDiff = toRow - fromRow;
 33→  const colDiff = Math.abs(toCol - fromCol);
 34→
 35→  // 1. Move forward 1 square
 36→  if (rowDiff === direction && colDiff === 0 && targetPiece === 0) {
 37→    return true;
 38→  }
 39→
 40→  // 2. Move forward 2 squares from starting position
 41→  if (
 42→    fromRow === startingRow &&
 43→    rowDiff === direction * 2 &&
 44→    colDiff === 0 &&
 45→    targetPiece === 0
 46→  ) {
 47→    // Check that the square in between is also empty
 48→    const middleIndex = rowColToIndex(fromRow + direction, fromCol);
 49→    if (board[middleIndex] === 0) {
 50→      return true;
 51→    }
 52→  }
 53→
 54→  // 3. Diagonal capture
 55→  if (rowDiff === direction && colDiff === 1) {
 56→    // Regular capture
 57→    if (targetPiece !== 0) {
 58→      // Check that target is opponent's piece
 59→      if (isWhite && isBlackPiece(targetPiece)) {
 60→        return true;
 61→      }
 62→      if (!isWhite && isWhitePiece(targetPiece)) {
 63→        return true;
 64→      }
 65→    }
 66→
 67→    // En passant capture
 68→    if (toIndex === enPassantTarget) {
 69→      return true;
 70→    }
 71→  }
 72→
 73→  return false;
 74→};
 75→
 76→// Check if move results in en passant opportunity
 77→export const getEnPassantTarget = (board, fromIndex, toIndex) => {
 78→  const piece = board[fromIndex];
 79→  const pieceType = Math.abs(piece);
 80→
 81→  if (pieceType !== PIECE_TYPES.PAWN) {
 82→    return null;
 83→  }
 84→
 85→  const { row: fromRow, col: fromCol } = indexToRowCol(fromIndex);
 86→  const { row: toRow, col: toCol } = indexToRowCol(toIndex);
 87→
 88→  const isWhite = isWhitePiece(piece);
 89→  const direction = isWhite ? -1 : 1;
 90→
 91→  // Check if pawn moved 2 squares
 92→  if (Math.abs(toRow - fromRow) === 2 && fromCol === toCol) {
 93→    // Return the square behind the pawn as the en passant target
 94→    return rowColToIndex(toRow - direction, toCol);
 95→  }
 96→
 97→  return null;
 98→};
 99→
100→// Check if pawn needs promotion
101→export const needsPromotion = (piece, toIndex) => {
102→  const pieceType = Math.abs(piece);
103→  if (pieceType !== PIECE_TYPES.PAWN) {
104→    return false;
105→  }
106→
107→  const { row } = indexToRowCol(toIndex);
108→  const isWhite = isWhitePiece(piece);
109→
110→  // White pawns promote on row 0, black pawns on row 7
111→  return (isWhite && row === 0) || (!isWhite && row === 7);
112→};
113→
114→// Helper to check if path is clear (no pieces in between)
115→const isPathClear = (board, fromIndex, toIndex) => {
116→  const { row: fromRow, col: fromCol } = indexToRowCol(fromIndex);
117→  const { row: toRow, col: toCol } = indexToRowCol(toIndex);
118→
119→  const rowStep = toRow > fromRow ? 1 : toRow < fromRow ? -1 : 0;
120→  const colStep = toCol > fromCol ? 1 : toCol < fromCol ? -1 : 0;
121→
122→  let currentRow = fromRow + rowStep;
123→  let currentCol = fromCol + colStep;
124→
125→  while (currentRow !== toRow || currentCol !== toCol) {
126→    const index = rowColToIndex(currentRow, currentCol);
127→    if (board[index] !== 0) {
128→      return false; // Path is blocked
129→    }
130→    currentRow += rowStep;
131→    currentCol += colStep;
132→  }
133→
134→  return true;
135→};
136→
137→// Validate rook moves
138→export const isValidRookMove = (board, fromIndex, toIndex) => {
139→  const piece = board[fromIndex];
140→  const targetPiece = board[toIndex];
141→  const pieceType = Math.abs(piece);
142→
143→  if (pieceType !== PIECE_TYPES.ROOK) {
144→    return false;
145→  }
146→
147→  const { row: fromRow, col: fromCol } = indexToRowCol(fromIndex);
148→  const { row: toRow, col: toCol } = indexToRowCol(toIndex);
149→
150→  // Rook moves horizontally or vertically
151→  const isHorizontal = fromRow === toRow && fromCol !== toCol;
152→  const isVertical = fromCol === toCol && fromRow !== toRow;
153→
154→  if (!isHorizontal && !isVertical) {
155→    return false; // Not a straight line
156→  }
157→
158→  // Check if path is clear
159→  if (!isPathClear(board, fromIndex, toIndex)) {
160→    return false;
161→  }
162→
163→  // Check destination square
164→  if (targetPiece !== 0) {
165→    // Can only capture opponent's piece
166→    const isWhite = isWhitePiece(piece);
167→    if (isWhite && isWhitePiece(targetPiece)) {
168→      return false; // Can't capture own piece
169→    }
170→    if (!isWhite && isBlackPiece(targetPiece)) {
171→      return false; // Can't capture own piece
172→    }
173→  }
174→
175→  return true;
176→};
177→
178→// Validate bishop moves
179→export const isValidBishopMove = (board, fromIndex, toIndex) => {
180→  const piece = board[fromIndex];
181→  const targetPiece = board[toIndex];
182→  const pieceType = Math.abs(piece);
183→
184→  if (pieceType !== PIECE_TYPES.BISHOP) {
185→    return false;
186→  }
187→
188→  const { row: fromRow, col: fromCol } = indexToRowCol(fromIndex);
189→  const { row: toRow, col: toCol } = indexToRowCol(toIndex);
190→
191→  const rowDiff = Math.abs(toRow - fromRow);
192→  const colDiff = Math.abs(toCol - fromCol);
193→
194→  // Bishop moves diagonally - row and column difference must be equal
195→  if (rowDiff !== colDiff || rowDiff === 0) {
196→    return false; // Not a diagonal move
197→  }
198→
199→  // Check if path is clear
200→  if (!isPathClear(board, fromIndex, toIndex)) {
201→    return false;
202→  }
203→
204→  // Check destination square
205→  if (targetPiece !== 0) {
206→    // Can only capture opponent's piece
207→    const isWhite = isWhitePiece(piece);
208→    if (isWhite && isWhitePiece(targetPiece)) {
209→      return false; // Can't capture own piece
210→    }
211→    if (!isWhite && isBlackPiece(targetPiece)) {
212→      return false; // Can't capture own piece
213→    }
214→  }
215→
216→  return true;
217→};
218→
219→// Helper function to check if a square is under attack by opponent
220→export const isSquareUnderAttack = (board, squareIndex, byColor) => {
221→  // byColor: 'white' or 'black' - the color attacking the square
222→  const { row: targetRow, col: targetCol } = indexToRowCol(squareIndex);
223→
224→  for (let i = 0; i < 64; i++) {
225→    const piece = board[i];
226→    if (piece === 0) continue;
227→
228→    const pieceIsWhite = isWhitePiece(piece);
229→    const pieceColor = pieceIsWhite ? 'white' : 'black';
230→
231→    // Only check pieces of the attacking color
232→    if (pieceColor !== byColor) continue;
233→
234→    const pieceType = Math.abs(piece);
235→
236→    // Check if this piece can attack the target square
237→    switch (pieceType) {
238→      case PIECE_TYPES.PAWN: {
239→        const { row: fromRow, col: fromCol } = indexToRowCol(i);
240→        const direction = pieceIsWhite ? -1 : 1;
241→        // Pawns attack diagonally
242→        if (fromRow + direction === targetRow && Math.abs(fromCol - targetCol) === 1) {
243→          return true;
244→        }
245→        break;
246→      }
247→      case PIECE_TYPES.KNIGHT:
248→        if (isValidKnightMove(board, i, squareIndex)) {
249→          return true;
250→        }
251→        break;
252→      case PIECE_TYPES.BISHOP:
253→        if (isValidBishopMove(board, i, squareIndex)) {
254→          return true;
255→        }
256→        break;
257→      case PIECE_TYPES.ROOK:
258→        if (isValidRookMove(board, i, squareIndex)) {
259→          return true;
260→        }
261→        break;
262→      case PIECE_TYPES.QUEEN:
263→        if (isValidQueenMove(board, i, squareIndex)) {
264→          return true;
265→        }
266→        break;
267→      case PIECE_TYPES.KING: {
268→        const { row: fromRow, col: fromCol } = indexToRowCol(i);
269→        // King attacks all adjacent squares
270→        if (Math.abs(fromRow - targetRow) <= 1 && Math.abs(fromCol - targetCol) <= 1) {
271→          return true;
272→        }
273→        break;
274→      }
275→    }
276→  }
277→
278→  return false;
279→};
280→
281→// Find the king's position on the board
282→const findKing = (board, isWhite) => {
283→  const kingValue = isWhite ? PIECE_TYPES.KING : -PIECE_TYPES.KING;
284→  for (let i = 0; i < 64; i++) {
285→    if (board[i] === kingValue) {
286→      return i;
287→    }
288→  }
289→  return null;
290→};
291→
292→// Check if the king is in check
293→export const isKingInCheck = (board, isWhite) => {
294→  const kingIndex = findKing(board, isWhite);
295→  if (kingIndex === null) return false;
296→
297→  const opponentColor = isWhite ? 'black' : 'white';
298→  return isSquareUnderAttack(board, kingIndex, opponentColor);
299→};
300→
301→// Validate king moves
302→export const isValidKingMove = (board, fromIndex, toIndex, hasMoved) => {
303→  const piece = board[fromIndex];
304→  const targetPiece = board[toIndex];
305→  const pieceType = Math.abs(piece);
306→
307→  if (pieceType !== PIECE_TYPES.KING) {
308→    return false;
309→  }
310→
311→  const { row: fromRow, col: fromCol } = indexToRowCol(fromIndex);
312→  const { row: toRow, col: toCol } = indexToRowCol(toIndex);
313→
314→  const rowDiff = Math.abs(toRow - fromRow);
315→  const colDiff = Math.abs(toCol - fromCol);
316→
317→  const isWhite = isWhitePiece(piece);
318→
319→  // Basic king move: 1 square in any direction
320→  if (rowDiff <= 1 && colDiff <= 1 && (rowDiff + colDiff > 0)) {
321→    // Check destination square
322→    if (targetPiece !== 0) {
323→      // Can only capture opponent's piece
324→      if (isWhite && isWhitePiece(targetPiece)) {
325→        return false;
326→      }
327→      if (!isWhite && isBlackPiece(targetPiece)) {
328→        return false;
329→      }
330→    }
331→
332→    // Check if move would put king in check
333→    const testBoard = [...board];
334→    testBoard[toIndex] = piece;
335→    testBoard[fromIndex] = 0;
336→
337→    if (isKingInCheck(testBoard, isWhite)) {
338→      return false; // Can't move into check
339→    }
340→
341→    return true;
342→  }
343→
344→  // Castling: king moves 2 squares horizontally
345→  if (rowDiff === 0 && colDiff === 2 && !hasMoved) {
346→    const direction = toCol > fromCol ? 1 : -1; // Right (kingside) or left (queenside)
347→    const rookCol = direction === 1 ? 7 : 0;
348→    const rookIndex = rowColToIndex(fromRow, rookCol);
349→    const rook = board[rookIndex];
350→
351→    // Check if rook exists and hasn't moved
352→    const expectedRook = isWhite ? PIECE_TYPES.ROOK : -PIECE_TYPES.ROOK;
353→    if (rook !== expectedRook) {
354→      return false;
355→    }
356→
357→    // Check if king is in check
358→    if (isKingInCheck(board, isWhite)) {
359→      return false;
360→    }
361→
362→    // Check if squares between king and rook are empty
363→    const start = Math.min(fromCol, rookCol) + 1;
364→    const end = Math.max(fromCol, rookCol);
365→    for (let col = start; col < end; col++) {
366→      const index = rowColToIndex(fromRow, col);
367→      if (board[index] !== 0) {
368→        return false; // Path is blocked
369→      }
370→    }
371→
372→    // Check if king passes through or ends in check
373→    for (let col = fromCol; col !== toCol + direction; col += direction) {
374→      const index = rowColToIndex(fromRow, col);
375→      const testBoard = [...board];
376→      testBoard[index] = piece;
377→      testBoard[fromIndex] = 0;
378→
379→      const opponentColor = isWhite ? 'black' : 'white';
380→      if (isSquareUnderAttack(testBoard, index, opponentColor)) {
381→        return false;
382→      }
383→    }
384→
385→    return true;
386→  }
387→
388→  return false;
389→};
390→
391→// Validate queen moves
392→export const isValidQueenMove = (board, fromIndex, toIndex) => {
393→  const piece = board[fromIndex];
394→  const pieceType = Math.abs(piece);
395→
396→  if (pieceType !== PIECE_TYPES.QUEEN) {
397→    return false;
398→  }
399→
400→  // Queen can move like a rook OR a bishop
401→  // Temporarily change piece type to test rook/bishop moves
402→  const tempRook = piece > 0 ? PIECE_TYPES.ROOK : -PIECE_TYPES.ROOK;
403→  const tempBishop = piece > 0 ? PIECE_TYPES.BISHOP : -PIECE_TYPES.BISHOP;
404→
405→  const tempBoard = [...board];
406→
407→  // Try as rook
408→  tempBoard[fromIndex] = tempRook;
409→  if (isValidRookMove(tempBoard, fromIndex, toIndex)) {
410→    return true;
411→  }
412→
413→  // Try as bishop
414→  tempBoard[fromIndex] = tempBishop;
415→  if (isValidBishopMove(tempBoard, fromIndex, toIndex)) {
416→    return true;
417→  }
418→
419→  return false;
420→};
421→
422→// Validate knight moves
423→export const isValidKnightMove = (board, fromIndex, toIndex) => {
424→  const piece = board[fromIndex];
425→  const targetPiece = board[toIndex];
426→  const pieceType = Math.abs(piece);
427→
428→  if (pieceType !== PIECE_TYPES.KNIGHT) {
429→    return false;
430→  }
431→
432→  const { row: fromRow, col: fromCol } = indexToRowCol(fromIndex);
433→  const { row: toRow, col: toCol } = indexToRowCol(toIndex);
434→
435→  const rowDiff = Math.abs(toRow - fromRow);
436→  const colDiff = Math.abs(toCol - fromCol);
437→
438→  // Knight moves in L-shape: 2 squares in one direction + 1 perpendicular
439→  const isLShape = (rowDiff === 2 && colDiff === 1) || (rowDiff === 1 && colDiff === 2);
440→
441→  if (!isLShape) {
442→    return false;
443→  }
444→
445→  // Knights can jump over pieces, so no path checking needed
446→
447→  // Check destination square
448→  if (targetPiece !== 0) {
449→    // Can only capture opponent's piece
450→    const isWhite = isWhitePiece(piece);
451→    if (isWhite && isWhitePiece(targetPiece)) {
452→      return false; // Can't capture own piece
453→    }
454→    if (!isWhite && isBlackPiece(targetPiece)) {
455→      return false; // Can't capture own piece
456→    }
457→  }
458→
459→  return true;
460→};
461→
462→// Check if checkmate
463→export const isCheckmate = (board, isWhite) => {
464→  const inCheck = isKingInCheck(board, isWhite);
465→
466→  for (let fromIndex = 0; fromIndex < 64; fromIndex++) {
467→    const piece = board[fromIndex];
468→    if (piece === 0) continue;
469→
470→    const pieceIsWhite = isWhitePiece(piece);
471→    if (pieceIsWhite !== isWhite) continue;
472→
473→    const pieceType = Math.abs(piece);
474→
475→    for (let toIndex = 0; toIndex < 64; toIndex++) {
476→      if (fromIndex === toIndex) continue;
477→
478→      let isValid = false;
479→
480→      switch (pieceType) {
481→        case PIECE_TYPES.PAWN:
482→          isValid = isValidPawnMove(board, fromIndex, toIndex, null);
483→          break;
484→        case PIECE_TYPES.KNIGHT:
485→          isValid = isValidKnightMove(board, fromIndex, toIndex);
486→          break;
487→        case PIECE_TYPES.BISHOP:
488→          isValid = isValidBishopMove(board, fromIndex, toIndex);
489→          break;
490→        case PIECE_TYPES.ROOK:
491→          isValid = isValidRookMove(board, fromIndex, toIndex);
492→          break;
493→        case PIECE_TYPES.QUEEN:
494→          isValid = isValidQueenMove(board, fromIndex, toIndex);
495→          break;
496→        case PIECE_TYPES.KING:
497→          isValid = isValidKingMove(board, fromIndex, toIndex, false);
498→          break;
499→      }
500→
501→      if (isValid) {
502→        const testBoard = [...board];
503→        testBoard[toIndex] = piece;
504→        testBoard[fromIndex] = 0;
505→
506→        if (!isKingInCheck(testBoard, isWhite)) {
507→          return false;
508→        }
509→      }
510→    }
511→  }
512→
513→  return inCheck;
514→};
515→
516→// Check for insufficient material (automatic draw)
517→export const isInsufficientMaterial = (board) => {
518→  const pieces = [];
519→  
520→  // Collect all pieces
521→  for (let i = 0; i < 64; i++) {
522→    if (board[i] !== 0) {
523→      pieces.push(Math.abs(board[i]));
524→    }
525→  }
526→
527→  // King vs King
528→  if (pieces.length === 2) {
529→    return true;
530→  }
531→
532→  // King + minor piece vs King
533→  if (pieces.length === 3) {
534→    const nonKings = pieces.filter(p => p !== PIECE_TYPES.KING);
535→    // Only bishop or knight
536→    if (nonKings.every(p => p === PIECE_TYPES.BISHOP || p === PIECE_TYPES.KNIGHT)) {
537→      return true;
538→    }
539→  }
540→
541→  // King + Bishop vs King + Bishop (same color squares)
542→  if (pieces.length === 4) {
543→    const bishops = [];
544→    for (let i = 0; i < 64; i++) {
545→      if (Math.abs(board[i]) === PIECE_TYPES.BISHOP) {
546→        const { row, col } = indexToRowCol(i);
547→        // Check if light or dark square
548→        bishops.push((row + col) % 2);
549→      }
550→    }
551→    // Both bishops on same color squares
552→    if (bishops.length === 2 && bishops[0] === bishops[1]) {
553→      return true;
554→    }
555→  }
556→
557→  return false;
558→};
559→
560→// Generate a position key for repetition detection
561→export const generatePositionKey = (board) => {
