  '-2': '♟',  // Black Pawn
  '-3': '♞',  // Black Knight
  '-4': '♜',  // Black Rook
  '-5': '♝',  // Black Bishop
  '-6': '♛',  // Black Queen
};

// FEN character to piece number mapping
