    fen += ' ' + (currentTurn === 'white' ? 'w' : 'b');

    // Castling availability
    fen += ' ' + castlingRights;

    // En passant target
    fen += ' ' + (enPassantTarget !== null ? this.indexToAlgebraic(enPassantTarget) : '-');

    // Halfmove clock and fullmove number
    fen += ` ${halfMoveClock} ${fullMoveNumber}`;

